/**
 * Custom YAML Validator Prototype
 * Tests basic syntax validation without external libraries
 * DISPOSABLE: For hypothesis testing only
 */

export interface ValidationError {
  line: number;
  column: number;
  type: string;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Simple YAML validator that detects common syntax errors.
 * Focus: indentation, quotes, braces, key-value pairs
 */
export class YamlValidator {
  private lines: string[];
  private errors: ValidationError[] = [];

  constructor(content: string) {
    this.lines = content.split('\n');
  }

  validate(): ValidationResult {
    this.errors = [];

    this.checkQuotes();
    this.checkIndentation();
    this.checkBraces();
    this.checkKeyValuePairs();
    this.checkDashes();

    return {
      valid: this.errors.length === 0,
      errors: this.errors
    };
  }

  private checkQuotes(): void {
    const quoteChars = ['"', "'"];
    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i];
      let inString = false;
      let stringChar = '';
      let escaped = false;

      for (let j = 0; j < line.length; j++) {
        const char = line[j];

        if (escaped) {
          escaped = false;
          continue;
        }

        if (char === '\\') {
          escaped = true;
          continue;
        }

        if (quoteChars.includes(char)) {
          if (!inString) {
            inString = true;
            stringChar = char;
          } else if (char === stringChar) {
            inString = false;
            stringChar = '';
          }
        }
      }

      if (inString) {
        this.errors.push({
          line: i + 1,
          column: line.length,
          type: 'UNCLOSED_QUOTE',
          message: `Unclosed ${stringChar === '"' ? 'double' : 'single'} quote`
        });
      }
    }
  }

  private checkIndentation(): void {
    let expectedIndent = 0;
    const indentStack: number[] = [0];

    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i];

      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) continue;

      const indent = this.getIndentation(line);

      // Check if indent is multiple of 2 (YAML standard)
      if (indent > 0 && indent % 2 !== 0) {
        this.errors.push({
          line: i + 1,
          column: indent + 1,
          type: 'BAD_INDENTATION',
          message: `Indentation must be multiple of 2 spaces (got ${indent})`
        });
      }

      // Track indent stack for structure validation
      if (indent > indentStack[indentStack.length - 1]) {
        indentStack.push(indent);
      } else if (indent < indentStack[indentStack.length - 1]) {
        // Pop until we find matching indent
        while (indentStack.length > 1 && indentStack[indentStack.length - 1] > indent) {
          indentStack.pop();
        }
        if (indent !== indentStack[indentStack.length - 1]) {
          this.errors.push({
            line: i + 1,
            column: 1,
            type: 'INCONSISTENT_INDENTATION',
            message: `Indentation does not match any previous level`
          });
        }
      }
    }
  }

  private checkBraces(): void {
    let bracketStack: Array<{type: string, line: number, col: number}> = [];
    const pairs: Record<string, string> = {'{': '}', '[': ']'};
    const closers = ['}', ']'];

    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i];
      let inString = false;
      let stringChar = '';

      for (let j = 0; j < line.length; j++) {
        const char = line[j];

        // Track string boundaries
        if ((char === '"' || char === "'") && (j === 0 || line[j-1] !== '\\')) {
          if (!inString) {
            inString = true;
            stringChar = char;
          } else if (char === stringChar) {
            inString = false;
          }
        }

        if (!inString) {
          if (char === '{' || char === '[') {
            bracketStack.push({type: char, line: i + 1, col: j + 1});
          } else if (char === '}' || char === ']') {
            if (bracketStack.length === 0) {
              this.errors.push({
                line: i + 1,
                column: j + 1,
                type: 'UNMATCHED_BRACE',
                message: `Closing '${char}' without opening bracket`
              });
            } else {
              const last = bracketStack[bracketStack.length - 1];
              const expectedCloser = pairs[last.type];
              if (expectedCloser !== char) {
                this.errors.push({
                  line: i + 1,
                  column: j + 1,
                  type: 'MISMATCHED_BRACE',
                  message: `Expected '${expectedCloser}' to close '${last.type}' on line ${last.line}`
                });
              }
              bracketStack.pop();
            }
          }
        }
      }
    }

    // Check for unclosed brackets
    for (const unclosed of bracketStack) {
      this.errors.push({
        line: unclosed.line,
        column: unclosed.col,
        type: 'UNCLOSED_BRACE',
        message: `Unclosed '${unclosed.type}' bracket`
      });
    }
  }

  private checkKeyValuePairs(): void {
    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i].trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) continue;

      // Skip array items
      if (line.startsWith('-')) continue;

      // Check for malformed key-value pairs
      // Valid patterns: "key: value", "key:", "- item", etc.
      if (line.includes(':')) {
        const colonIndex = line.indexOf(':');
        const beforeColon = line.substring(0, colonIndex).trim();

        // Check if key is empty
        if (!beforeColon) {
          this.errors.push({
            line: i + 1,
            column: colonIndex + 1,
            type: 'MALFORMED_KEY_VALUE',
            message: 'Missing key before colon'
          });
        }

        // Check for double colons (common error)
        if (line.includes('::')) {
          this.errors.push({
            line: i + 1,
            column: line.indexOf('::') + 1,
            type: 'SYNTAX_ERROR',
            message: 'Double colon not allowed (use single colon for key-value pairs)'
          });
        }
      }
    }
  }

  private checkDashes(): void {
    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i];
      const trimmed = line.trim();

      // Check for misplaced dashes in arrays
      if (trimmed.startsWith('- ')) {
        const indent = this.getIndentation(line);
        // Verify proper indentation for array items
        if (indent > 0 && indent % 2 !== 0) {
          this.errors.push({
            line: i + 1,
            column: indent + 1,
            type: 'ARRAY_INDENT_ERROR',
            message: 'Array items must be indented at proper levels'
          });
        }
      }
    }
  }

  private getIndentation(line: string): number {
    let count = 0;
    for (let i = 0; i < line.length; i++) {
      if (line[i] === ' ') count++;
      else break;
    }
    return count;
  }
}

/**
 * Test Suite for YAML Validator Prototype
 * DISPOSABLE: For hypothesis testing only
 */

import { YamlValidator, ValidationResult } from './yaml-validator';
import { describe, test, expect } from 'bun:test';

describe('YamlValidator', () => {

  describe('Valid YAML Detection', () => {
    test('detects valid simple key-value', () => {
      const yaml = 'name: John\nage: 30';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test('detects valid nested structure', () => {
      const yaml = `person:
  name: John
  age: 30`;
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test('detects valid arrays', () => {
      const yaml = `items:
  - apple
  - banana
  - orange`;
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test('detects valid comments', () => {
      const yaml = `# This is a comment
name: John  # inline comment
age: 30`;
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test('handles empty lines', () => {
      const yaml = `name: John

age: 30`;
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });
  });

  describe('Unclosed Quotes Detection', () => {
    test('detects unclosed double quote', () => {
      const yaml = 'name: "John';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const unclosedError = result.errors.find(e => e.type === 'UNCLOSED_QUOTE');
      expect(unclosedError).toBeDefined();
    });

    test('detects unclosed single quote', () => {
      const yaml = "name: 'John";
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const unclosedError = result.errors.find(e => e.type === 'UNCLOSED_QUOTE');
      expect(unclosedError).toBeDefined();
    });

    test('allows escaped quotes', () => {
      const yaml = 'name: "John \\"Doe\\""';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);
    });
  });

  describe('Indentation Errors Detection', () => {
    test('detects odd-number indentation', () => {
      const yaml = `person:
   name: John`;  // 3 spaces
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const indentError = result.errors.find(e => e.type === 'BAD_INDENTATION');
      expect(indentError).toBeDefined();
    });

    test('detects inconsistent indentation', () => {
      const yaml = `person:
  name: John
   age: 30`;  // 3 spaces on second nested item
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const indentError = result.errors.find(e =>
        e.type === 'BAD_INDENTATION' || e.type === 'INCONSISTENT_INDENTATION'
      );
      expect(indentError).toBeDefined();
    });
  });

  describe('Brace Mismatch Detection', () => {
    test('detects unmatched closing brace', () => {
      const yaml = 'config: {name: John}';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(true);  // Valid JSON-style YAML
    });

    test('detects mismatched brackets', () => {
      const yaml = 'items: [apple, banana}';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const braceError = result.errors.find(e =>
        e.type === 'MISMATCHED_BRACE' || e.type === 'UNMATCHED_BRACE'
      );
      expect(braceError).toBeDefined();
    });

    test('detects unclosed brace', () => {
      const yaml = 'config: {name: John';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const unclosedError = result.errors.find(e => e.type === 'UNCLOSED_BRACE');
      expect(unclosedError).toBeDefined();
    });
  });

  describe('Key-Value Pair Errors', () => {
    test('detects missing key before colon', () => {
      const yaml = ': value';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const kvError = result.errors.find(e => e.type === 'MALFORMED_KEY_VALUE');
      expect(kvError).toBeDefined();
    });

    test('detects double colons', () => {
      const yaml = 'name:: John';
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      expect(result.valid).toBe(false);
      const syntaxError = result.errors.find(e => e.type === 'SYNTAX_ERROR');
      expect(syntaxError).toBeDefined();
    });
  });

  describe('Error Line Numbers', () => {
    test('provides accurate line numbers', () => {
      const yaml = `name: John
age: "30
city: New York`;
      const validator = new YamlValidator(yaml);
      const result = validator.validate();
      const quoteError = result.errors.find(e => e.type === 'UNCLOSED_QUOTE');
      expect(quoteError?.line).toBe(2);
    });
  });
});

