/**
 * Test Bun.file() error code compatibility with Node.js conventions
 * DISPOSABLE: For hypothesis testing only
 */

import { describe, test, expect, beforeAll, afterAll } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';

describe('Bun.file() Error Code Compatibility', () => {
  const testDir = '/tmp/bun-file-test';
  const validFile = path.join(testDir, 'valid.txt');
  const nonexistentFile = path.join(testDir, 'nonexistent.txt');

  beforeAll(() => {
    // Create test directory
    if (!fs.existsSync(testDir)) {
      fs.mkdirSync(testDir, { recursive: true });
    }
    // Create a valid file
    fs.writeFileSync(validFile, 'test content');
  });

  afterAll(() => {
    // Cleanup
    if (fs.existsSync(testDir)) {
      fs.rmSync(testDir, { recursive: true });
    }
  });

  describe('ENOENT - File Not Found', () => {
    test('error has code property for nonexistent file', async () => {
      try {
        const result = await Bun.file(nonexistentFile).text();
        expect(result).toBeDefined(); // Should not reach here
      } catch (error: any) {
        expect(error).toBeDefined();
        expect(error.code).toBeDefined();
        expect(error.code).toBe('ENOENT');
        expect(error.message).toContain('No such file');
      }
    });

    test('error object structure for ENOENT', async () => {
      try {
        await Bun.file(nonexistentFile).text();
      } catch (error: any) {
        // Check for standard Node.js fs error properties
        expect(typeof error.code).toBe('string');
        expect(error.message).toBeDefined();
        expect(typeof error.message).toBe('string');
        expect(error.path === undefined || typeof error.path === 'string').toBe(true);
      }
    });
  });

  describe('Valid File Read', () => {
    test('successfully reads existing file', async () => {
      const content = await Bun.file(validFile).text();
      expect(content).toBe('test content');
    });
  });

  describe('Error Message Quality', () => {
    test('error messages are descriptive', async () => {
      try {
        await Bun.file(nonexistentFile).text();
      } catch (error: any) {
        // Error message should be user-friendly
        expect(error.message.length).toBeGreaterThan(0);
        expect(error.message.toLowerCase()).toContain('no such file');
      }
    });
  });

  describe('Error Handling Pattern', () => {
    test('standard Node.js error handling pattern works', async () => {
      let errorHandled = false;

      try {
        await Bun.file(nonexistentFile).text();
      } catch (error: any) {
        if (error.code === 'ENOENT') {
          errorHandled = true;
        }
      }

      expect(errorHandled).toBe(true);
    });

    test('can distinguish error types by code', async () => {
      const errors: Record<string, boolean> = {
        ENOENT: false,
        EACCES: false,
        OTHER: false
      };

      // Test ENOENT
      try {
        await Bun.file(nonexistentFile).text();
      } catch (error: any) {
        if (error.code === 'ENOENT') {
          errors.ENOENT = true;
        } else {
          errors.OTHER = true;
        }
      }

      expect(errors.ENOENT).toBe(true);
      expect(errors.OTHER).toBe(false);
    });
  });
});

