/**
 * Utility functions for the eval test project.
 */

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Result of YAML syntax validation.
 */
export interface YamlValidationResult {
  valid: boolean;
  error?: {
    line: number;
    column?: number;
    message: string;
  };
}

/**
 * Validates YAML syntax for basic structural correctness.
 *
 * Checks for common YAML syntax errors including:
 * - Inconsistent or tab-based indentation
 * - Unclosed quotes (single and double)
 * - Unbalanced brackets and braces
 * - Invalid key-value pair syntax
 * - Invalid array markers
 *
 * Does NOT validate against YAML schema, resolve anchors/aliases,
 * or handle complex multiline string semantics.
 *
 * @param content - YAML content as string
 * @returns YamlValidationResult with valid flag and error details if invalid
 *
 * @example
 * const result = validateYamlSyntax("key: value");
 * if (result.valid) {
 *   console.log("YAML is valid");
 * } else {
 *   console.log(`Error at line ${result.error.line}: ${result.error.message}`);
 * }
 */
export function validateYamlSyntax(content: string): YamlValidationResult {
  const lines = content.split("\n");

  // State tracking for validation
  const indentStack: number[] = [];
  let inMultilineString = false;
  let multilineMarker = "";

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const lineNumber = lineNum + 1;

    // Skip empty lines
    if (line.trim() === "") {
      continue;
    }

    // Remove comments (but be careful with # in strings)
    let processedLine = removeComments(line);

    // Skip if line becomes empty after comment removal
    if (processedLine.trim() === "") {
      continue;
    }

    // Check for multiline string markers (|, >, |-, >-)
    if (!inMultilineString && isMultilineMarker(processedLine)) {
      inMultilineMarker = getMultilineMarker(processedLine);
      inMultilineString = true;
      continue;
    }

    // Check if we're exiting multiline string
    if (inMultilineString) {
      const currentIndent = getIndentation(line);
      const expectedIndent = indentStack[indentStack.length - 1] ?? 0;
      if (line.trim() !== "" && currentIndent <= expectedIndent) {
        inMultilineString = false;
      } else {
        continue;
      }
    }

    // Validate indentation (spaces only, no tabs)
    const indentMatch = line.match(/^(\s*)/);
    if (indentMatch && indentMatch[1].includes("\t")) {
      return {
        valid: false,
        error: {
          line: lineNumber,
          column: 1,
          message: "Tabs are not allowed in YAML; use spaces only",
        },
      };
    }

    // Get indentation level
    const currentIndent = getIndentation(line);

    // Validate indentation consistency
    if (indentStack.length > 0) {
      const parentIndent = indentStack[indentStack.length - 1];
      if (currentIndent > parentIndent && currentIndent % 2 !== 0) {
        // Allow indentation that's not a multiple of 2, but warn if inconsistent
        const diff = currentIndent - parentIndent;
        if (diff !== 2) {
          // Allow any consistent increment for flexibility
        }
      }
    }

    // Check for quote pairing
    const quoteError = validateQuotes(processedLine, lineNumber);
    if (quoteError) {
      return quoteError;
    }

    // Check for bracket/brace balance
    const bracketError = validateBrackets(processedLine, lineNumber);
    if (bracketError) {
      return bracketError;
    }

    // Check for key-value syntax
    const colonError = validateColonSyntax(processedLine, lineNumber);
    if (colonError) {
      return colonError;
    }

    // Check array marker syntax
    const arrayError = validateArrayMarker(processedLine, lineNumber);
    if (arrayError) {
      return arrayError;
    }

    // Update indent stack based on content
    updateIndentStack(indentStack, currentIndent, processedLine);
  }

  return { valid: true };
}

/**
 * Remove comments from a line while respecting quoted strings.
 */
function removeComments(line: string): string {
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let result = "";

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    if (char === "'" && prevChar !== "\\" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      result += char;
    } else if (char === '"' && prevChar !== "\\" && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      result += char;
    } else if (char === "#" && !inSingleQuote && !inDoubleQuote) {
      // Rest of line is a comment
      break;
    } else {
      result += char;
    }
  }

  return result;
}

/**
 * Check if line contains multiline string marker.
 */
function isMultilineMarker(line: string): boolean {
  const trimmed = line.trim();
  return /[|>][-+]?\s*$/.test(trimmed);
}

/**
 * Get the multiline marker from a line.
 */
function getMultilineMarker(line: string): string {
  const match = line.match(/([|>][-+]?)/);
  return match ? match[1] : "";
}

/**
 * Calculate indentation level (number of leading spaces).
 */
function getIndentation(line: string): number {
  const match = line.match(/^( *)/);
  return match ? match[1].length : 0;
}

/**
 * Validate quote pairing in a line.
 */
function validateQuotes(
  line: string,
  lineNumber: number
): YamlValidationResult | null {
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    if (char === "'" && prevChar !== "\\") {
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && prevChar !== "\\") {
      inDoubleQuote = !inDoubleQuote;
    }
  }

  if (inSingleQuote) {
    return {
      valid: false,
      error: {
        line: lineNumber,
        message: "Unclosed single quote",
      },
    };
  }

  if (inDoubleQuote) {
    return {
      valid: false,
      error: {
        line: lineNumber,
        message: "Unclosed double quote",
      },
    };
  }

  return null;
}

/**
 * Validate bracket and brace balance.
 */
function validateBrackets(
  line: string,
  lineNumber: number
): YamlValidationResult | null {
  const stack: string[] = [];
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    if (char === "'" && prevChar !== "\\" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      continue;
    }

    if (char === '"' && prevChar !== "\\" && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      continue;
    }

    // Skip if inside quotes
    if (inSingleQuote || inDoubleQuote) {
      continue;
    }

    if (char === "{" || char === "[" || char === "(") {
      stack.push(char);
    } else if (char === "}") {
      if (stack.length === 0 || stack[stack.length - 1] !== "{") {
        return {
          valid: false,
          error: {
            line: lineNumber,
            column: i + 1,
            message: "Unbalanced closing brace",
          },
        };
      }
      stack.pop();
    } else if (char === "]") {
      if (stack.length === 0 || stack[stack.length - 1] !== "[") {
        return {
          valid: false,
          error: {
            line: lineNumber,
            column: i + 1,
            message: "Unbalanced closing bracket",
          },
        };
      }
      stack.pop();
    } else if (char === ")") {
      if (stack.length === 0 || stack[stack.length - 1] !== "(") {
        return {
          valid: false,
          error: {
            line: lineNumber,
            column: i + 1,
            message: "Unbalanced closing parenthesis",
          },
        };
      }
      stack.pop();
    }
  }

  if (stack.length > 0) {
    return {
      valid: false,
      error: {
        line: lineNumber,
        message: `Unclosed ${
          stack[stack.length - 1] === "{" ? "brace" : "bracket"
        }`,
      },
    };
  }

  return null;
}

/**
 * Validate key-value colon syntax.
 */
function validateColonSyntax(
  line: string,
  lineNumber: number
): YamlValidationResult | null {
  const trimmed = line.trim();

  // Skip lines that don't contain colons or are just comments
  if (!trimmed.includes(":") || trimmed.startsWith("-")) {
    return null;
  }

  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < trimmed.length; i++) {
    const char = trimmed[i];
    const prevChar = i > 0 ? trimmed[i - 1] : "";

    if (char === "'" && prevChar !== "\\" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && prevChar !== "\\" && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (char === ":" && !inSingleQuote && !inDoubleQuote) {
      // Colon found outside quotes
      // Valid if it's at end of line or followed by space or special char
      const nextChar = i + 1 < trimmed.length ? trimmed[i + 1] : "";
      if (nextChar && nextChar !== " " && nextChar !== "#") {
        // Allow URLs (http:, https:, etc)
        if (!["h", "f"].includes(nextChar)) {
          return {
            valid: false,
            error: {
              line: lineNumber,
              column: i + 1,
              message: "Invalid colon placement (must be followed by space or end of line)",
            },
          };
        }
      }
    }
  }

  return null;
}

/**
 * Validate array marker (-) placement.
 */
function validateArrayMarker(
  line: string,
  lineNumber: number
): YamlValidationResult | null {
  const trimmed = line.trim();

  // Check for standalone dash at start of trimmed line
  if (trimmed.startsWith("-")) {
    const afterDash = trimmed.substring(1);
    // Should be followed by space or be end of line (for empty array items)
    if (afterDash && !afterDash.startsWith(" ")) {
      // Unless it's part of a negative number or date
      if (!afterDash[0].match(/[0-9]/)) {
        return {
          valid: false,
          error: {
            line: lineNumber,
            message: "Invalid array marker (dash must be followed by space)",
          },
        };
      }
    }
  }

  return null;
}

/**
 * Update indentation stack based on line content.
 */
function updateIndentStack(
  stack: number[],
  indent: number,
  line: string
): void {
  // Pop stack if indentation decreased
  while (stack.length > 0 && indent < stack[stack.length - 1]) {
    stack.pop();
  }

  // Add to stack if this line indicates a nested structure
  if (
    line.includes(":") &&
    !line.trim().startsWith("-") &&
    !line.endsWith(":")
  ) {
    // Key-value pair that might have nested content
    if (stack.length === 0 || indent > stack[stack.length - 1]) {
      stack.push(indent);
    }
  } else if (line.trim().startsWith("-")) {
    // Array item
    if (stack.length === 0 || indent > stack[stack.length - 1]) {
      stack.push(indent);
    }
  }
}

