import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { validateYamlSyntax } from "./utils";
import { writeFileSync, unlinkSync } from "fs";
import { existsSync } from "fs";

/**
 * Integration tests for YAML validator.
 *
 * Tests cover:
 * - Valid YAML syntax detection
 * - Invalid YAML syntax detection (unclosed quotes, bad indentation, unbalanced braces)
 * - File I/O error handling (file not found, permission denied)
 * - Output message formatting and exit codes
 * - Backward compatibility with existing commands
 */

describe("yaml validator - syntax validation", () => {
  test("valid YAML with simple key-value pairs", () => {
    const yaml = "name: my-app\nversion: 1.0.0";
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("valid YAML with nested structure", () => {
    const yaml = `app:
  name: my-app
  version: 1.0.0
  features:
    - logging
    - monitoring`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with array items", () => {
    const yaml = `items:
  - name: item1
    value: 100
  - name: item2
    value: 200`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with quoted strings", () => {
    const yaml = `name: "quoted value"
description: 'another quoted'`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

