    expect(result.error?.line).toBeGreaterThan(0);
  });

  test("complex valid YAML structure", () => {
    const content = `version: 1.0
metadata:
  name: complex-app
  version: 2.0
  tags:
    - production
    - critical
config:
  database:
    host: localhost
    port: 5432
    credentials:
      user: admin
      password: "secret123"
  cache:
    enabled: true
    ttl: 3600
features:
  - name: feature-1
    enabled: true
  - name: feature-2
    enabled: false
    config:
      timeout: 30`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with special characters in strings", () => {
    const content = `special: "value with @#$%^&*() chars"
path: /home/user/docs/file.txt
math: 2+2=4`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with numeric values", () => {
    const content = `integer: 42
float: 3.14
negative: -100
scientific: 1.2e-3
hex: 0x1a`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with boolean values", () => {
    const content = `enabled: true
disabled: false
yes_val: yes
no_val: no`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with null values", () => {
    const content = `null_value: null
tilde_value: ~
empty: `;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });
});

describe("yaml validator - edge cases", () => {
