+/**
+ * Result of YAML syntax validation.
+ */
+export interface YamlValidationResult {
+  valid: boolean;
+  error?: {
+    line: number;
+    column?: number;
+    message: string;
+  };
+}
+
+/**
+ * Validates YAML syntax for basic structural correctness.
+ *
+ * Checks for common YAML syntax errors including:
+ * - Inconsistent or tab-based indentation
+ * - Unclosed quotes (single and double)
+ * - Unbalanced brackets and braces
+ * - Invalid key-value pair syntax
+ * - Invalid array markers
+ *
+ * Does NOT validate against YAML schema, resolve anchors/aliases,
+ * or handle complex multiline string semantics.
+ *
+ * @param content - YAML content as string
+ * @returns YamlValidationResult with valid flag and error details if invalid
+ *
+ * @example
+ * const result = validateYamlSyntax("key: value");
+ * if (result.valid) {
+ *   console.log("YAML is valid");
+ * } else {
+ *   console.log(`Error at line ${result.error.line}: ${result.error.message}`);
+ * }
+ */
+export function validateYamlSyntax(content: string): YamlValidationResult {
+  const lines = content.split("\n");
+
+  // State tracking for validation
+  const indentStack: number[] = [];
+  let inMultilineString = false;
+  let multilineMarker = "";
+
+  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
+    const line = lines[lineNum];
+    const lineNumber = lineNum + 1;
+
+    // Skip empty lines
+    if (line.trim() === "") {
+      continue;
+    }
+
+    // Remove comments (but be careful with # in strings)
+    let processedLine = removeComments(line);
+
+    // Skip if line becomes empty after comment removal
+    if (processedLine.trim() === "") {
+      continue;
+    }
+
+    // Check for multiline string markers (|, >, |-, >-)
+    if (!inMultilineString && isMultilineMarker(processedLine)) {
+      multilineMarker = getMultilineMarker(processedLine);
+      inMultilineString = true;
+      continue;
+    }
+
+    // Check if we're exiting multiline string
+    if (inMultilineString) {
+      const currentIndent = getIndentation(line);
+      const expectedIndent = indentStack[indentStack.length - 1] ?? 0;
+      if (line.trim() !== "" && currentIndent <= expectedIndent) {
+        inMultilineString = false;
+      } else {
+        continue;
+      }
+    }
+
+    // Validate indentation (spaces only, no tabs)
+    const indentMatch = line.match(/^(\s*)/);
+    if (indentMatch && indentMatch[1].includes("\t")) {
+      return {
+        valid: false,
+        error: {
+          line: lineNumber,
+          column: 1,
+          message: "Tabs are not allowed in YAML; use spaces only",
+        },
+      };
+    }

