    19→/**
    20→ * Result of YAML syntax validation.
    21→ */
    22→export interface YamlValidationResult {
    23→  valid: boolean;
    24→  error?: {
    25→    line: number;
    26→    column?: number;
    27→    message: string;
    28→  };
    29→}
    30→
    31→/**
    32→ * Validates YAML syntax for basic structural correctness.
    33→ *
    34→ * Checks for common YAML syntax errors including:
    35→ * - Inconsistent or tab-based indentation
    36→ * - Unclosed quotes (single and double)
    37→ * - Unbalanced brackets and braces
    38→ * - Invalid key-value pair syntax
    39→ * - Invalid array markers
    40→ *
    41→ * Does NOT validate against YAML schema, resolve anchors/aliases,
    42→ * or handle complex multiline string semantics.
    43→ *
    44→ * @param content - YAML content as string
    45→ * @returns YamlValidationResult with valid flag and error details if invalid
    46→ *
    47→ * @example
    48→ * const result = validateYamlSyntax("key: value");
    49→ * if (result.valid) {
    50→ *   console.log("YAML is valid");
    51→ * } else {
    52→ *   console.log(`Error at line ${result.error.line}: ${result.error.message}`);
    53→ * }
    54→ */
    55→export function validateYamlSyntax(content: string): YamlValidationResult {
    56→  const lines = content.split("\n");
    57→
    58→  // State tracking for validation
    59→  const indentStack: number[] = [];
    60→  let inMultilineString = false;
    61→  let multilineMarker = "";
    62→
    63→  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    64→    const line = lines[lineNum];
    65→    const lineNumber = lineNum + 1;
    66→
    67→    // Skip empty lines
    68→    if (line.trim() === "") {
    69→      continue;
    70→    }
    71→
    72→    // Remove comments (but be careful with # in strings)
    73→    let processedLine = removeComments(line);
    74→
    75→    // Skip if line becomes empty after comment removal
    76→    if (processedLine.trim() === "") {
    77→      continue;
    78→    }
    79→
    80→    // Check for multiline string markers (|, >, |-, >-)
    81→    if (!inMultilineString && isMultilineMarker(processedLine)) {
    82→      multilineMarker = getMultilineMarker(processedLine);
    83→      inMultilineString = true;
    84→      continue;
    85→    }
    86→
    87→    // Check if we're exiting multiline string
    88→    if (inMultilineString) {
    89→      const currentIndent = getIndentation(line);
    90→      const expectedIndent = indentStack[indentStack.length - 1] ?? 0;
    91→      if (line.trim() !== "" && currentIndent <= expectedIndent) {
    92→        inMultilineString = false;
    93→      } else {
    94→        continue;
    95→      }
    96→    }
    97→
    98→    // Validate indentation (spaces only, no tabs)
    99→    const indentMatch = line.match(/^(\s*)/);
   100→    if (indentMatch && indentMatch[1].includes("\t")) {
   101→      return {
   102→        valid: false,
   103→        error: {
   104→          line: lineNumber,
   105→          column: 1,
   106→          message: "Tabs are not allowed in YAML; use spaces only",
   107→        },
   108→      };
   109→    }
   110→
   111→    // Get indentation level
   112→    const currentIndent = getIndentation(line);
   113→
   114→    // Validate indentation consistency
   115→    if (indentStack.length > 0) {
   116→      const parentIndent = indentStack[indentStack.length - 1];
   117→      if (currentIndent > parentIndent && currentIndent % 2 !== 0) {
   118→        // Allow indentation that's not a multiple of 2, but warn if inconsistent
   119→        const diff = currentIndent - parentIndent;
   120→        if (diff !== 2) {
   121→          // Allow any consistent increment for flexibility
   122→        }
   123→      }
   124→    }
   125→
   126→    // Check for quote pairing
   127→    const quoteError = validateQuotes(processedLine, lineNumber);
   128→    if (quoteError) {
   129→      return quoteError;
   130→    }
   131→
   132→    // Check for bracket/brace balance
   133→    const bracketError = validateBrackets(processedLine, lineNumber);
   134→    if (bracketError) {
   135→      return bracketError;
   136→    }
   137→
   138→    // Check for key-value syntax
   139→    const colonError = validateColonSyntax(processedLine, lineNumber);
   140→    if (colonError) {
   141→      return colonError;
   142→    }
   143→
   144→    // Check array marker syntax
   145→    const arrayError = validateArrayMarker(processedLine, lineNumber);
   146→    if (arrayError) {
   147→      return arrayError;
   148→    }
   149→
   150→    // Update indent stack based on content
   151→    updateIndentStack(indentStack, currentIndent, processedLine);
   152→  }
   153→
   154→  return { valid: true };
   155→}
   156→
   157→/**
   158→ * Remove comments from a line while respecting quoted strings.
   159→ */
   160→function removeComments(line: string): string {
   161→  let inSingleQuote = false;
   162→  let inDoubleQuote = false;
   163→  let result = "";
   164→
   165→  for (let i = 0; i < line.length; i++) {
   166→    const char = line[i];
   167→    const prevChar = i > 0 ? line[i - 1] : "";
   168→
   169→    if (char === "'" && prevChar !== "\\" && !inDoubleQuote) {
   170→      inSingleQuote = !inSingleQuote;
   171→      result += char;
   172→    } else if (char === '"' && prevChar !== "\\" && !inSingleQuote) {
   173→      inDoubleQuote = !inDoubleQuote;
   174→      result += char;
   175→    } else if (char === "#" && !inSingleQuote && !inDoubleQuote) {
   176→      // Rest of line is a comment
   177→      break;
   178→    } else {
   179→      result += char;
   180→    }
   181→  }
   182→
   183→  return result;
   184→}
   185→
   186→/**
   187→ * Check if line contains multiline string marker.
   188→ */
   189→function isMultilineMarker(line: string): boolean {
   190→  const trimmed = line.trim();
   191→  return /[|>][-+]?\s*$/.test(trimmed);
   192→}
   193→
   194→/**
   195→ * Get the multiline marker from a line.
   196→ */
   197→function getMultilineMarker(line: string): string {
   198→  const match = line.match(/([|>][-+]?)/);
   199→  return match ? match[1] : "";
   200→}
   201→
   202→/**
   203→ * Calculate indentation level (number of leading spaces).
   204→ */
   205→function getIndentation(line: string): number {
   206→  const match = line.match(/^( *)/);
   207→  return match ? match[1].length : 0;
   208→}
   209→
   210→/**
   211→ * Validate quote pairing in a line.
   212→ */
   213→function validateQuotes(
   214→  line: string,
   215→  lineNumber: number
   216→): YamlValidationResult | null {
   217→  let inSingleQuote = false;
   218→  let inDoubleQuote = false;
   219→
   220→  for (let i = 0; i < line.length; i++) {
   221→    const char = line[i];
   222→    const prevChar = i > 0 ? line[i - 1] : "";
   223→
   224→    if (char === "'" && prevChar !== "\\") {
   225→      inSingleQuote = !inSingleQuote;
   226→    } else if (char === '"' && prevChar !== "\\") {
   227→      inDoubleQuote = !inDoubleQuote;
   228→    }
   229→  }
   230→
   231→  if (inSingleQuote) {
   232→    return {
   233→      valid: false,
   234→      error: {
   235→        line: lineNumber,
   236→        message: "Unclosed single quote",
   237→      },
   238→    };
   239→  }
   240→
   241→  if (inDoubleQuote) {
   242→    return {
   243→      valid: false,
   244→      error: {
   245→        line: lineNumber,
   246→        message: "Unclosed double quote",
   247→      },
   248→    };
   249→  }
   250→
   251→  return null;
   252→}
   253→
   254→/**
   255→ * Validate bracket and brace balance.
   256→ */
   257→function validateBrackets(
   258→  line: string,
   259→  lineNumber: number
   260→): YamlValidationResult | null {
   261→  const stack: string[] = [];
   262→  let inSingleQuote = false;
   263→  let inDoubleQuote = false;
   264→
   265→  for (let i = 0; i < line.length; i++) {
   266→    const char = line[i];
   267→    const prevChar = i > 0 ? line[i - 1] : "";
   268→
   269→    if (char === "'" && prevChar !== "\\" && !inDoubleQuote) {
   270→      inSingleQuote = !inSingleQuote;
   271→      continue;
   272→    }
   273→
   274→    if (char === '"' && prevChar !== "\\" && !inSingleQuote) {
   275→      inDoubleQuote = !inDoubleQuote;
   276→      continue;
   277→    }
   278→
   279→    // Skip if inside quotes
   280→    if (inSingleQuote || inDoubleQuote) {
   281→      continue;
   282→    }
   283→
   284→    if (char === "{" || char === "[" || char === "(") {
   285→      stack.push(char);
   286→    } else if (char === "}") {
   287→      if (stack.length === 0 || stack[stack.length - 1] !== "{") {
   288→        return {
   289→          valid: false,
   290→          error: {
   291→            line: lineNumber,
   292→            column: i + 1,
   293→            message: "Unbalanced closing brace",
   294→          },
   295→        };
   296→      }
   297→      stack.pop();
   298→    } else if (char === "]") {
   299→      if (stack.length === 0 || stack[stack.length - 1] !== "[") {
   300→        return {
   301→          valid: false,
   302→          error: {
   303→            line: lineNumber,
   304→            column: i + 1,
   305→            message: "Unbalanced closing bracket",
   306→          },
   307→        };
   308→      }
   309→      stack.pop();
   310→    } else if (char === ")") {
   311→      if (stack.length === 0 || stack[stack.length - 1] !== "(") {
   312→        return {
   313→          valid: false,
   314→          error: {
   315→            line: lineNumber,
   316→            column: i + 1,
   317→            message: "Unbalanced closing parenthesis",
   318→          },
   319→        };
   320→      }
   321→      stack.pop();
   322→    }
   323→  }
   324→
   325→  if (stack.length > 0) {
   326→    return {
   327→      valid: false,
   328→      error: {
   329→        line: lineNumber,
   330→        message: `Unclosed ${
   331→          stack[stack.length - 1] === "{" ? "brace" : "bracket"
   332→        }`,
   333→      },
   334→    };
   335→  }
   336→
   337→  return null;
   338→}
   339→
   340→/**
   341→ * Validate key-value colon syntax.
   342→ */
   343→function validateColonSyntax(
   344→  line: string,
   345→  lineNumber: number
   346→): YamlValidationResult | null {
   347→  const trimmed = line.trim();
   348→
   349→  // Skip lines that don't contain colons or are just comments
   350→  if (!trimmed.includes(":") || trimmed.startsWith("-")) {
   351→    return null;
   352→  }
   353→
   354→  let inSingleQuote = false;
   355→  let inDoubleQuote = false;
   356→
   357→  for (let i = 0; i < trimmed.length; i++) {
   358→    const char = trimmed[i];
   359→    const prevChar = i > 0 ? trimmed[i - 1] : "";
   360→
   361→    if (char === "'" && prevChar !== "\\" && !inDoubleQuote) {
   362→      inSingleQuote = !inSingleQuote;
   363→    } else if (char === '"' && prevChar !== "\\" && !inSingleQuote) {
   364→      inDoubleQuote = !inDoubleQuote;
   365→    } else if (char === ":" && !inSingleQuote && !inDoubleQuote) {
   366→      // Colon found outside quotes
   367→      // Valid if it's at end of line or followed by space or special char
   368→      const nextChar = i + 1 < trimmed.length ? trimmed[i + 1] : "";
   369→      if (nextChar && nextChar !== " " && nextChar !== "#") {
   370→        // Allow URLs (http:, https:, etc)
   371→        if (!["h", "f"].includes(nextChar)) {
   372→          return {
   373→            valid: false,
   374→            error: {
   375→              line: lineNumber,
   376→              column: i + 1,
   377→              message: "Invalid colon placement (must be followed by space or end of line)",
   378→            },
   379→          };
   380→        }
   381→      }
   382→    }
   383→  }
   384→
   385→  return null;
   386→}
   387→
   388→/**
   389→ * Validate array marker (-) placement.
   390→ */
   391→function validateArrayMarker(
   392→  line: string,
   393→  lineNumber: number
   394→): YamlValidationResult | null {
   395→  const trimmed = line.trim();
   396→
   397→  // Check for standalone dash at start of trimmed line
   398→  if (trimmed.startsWith("-")) {
   399→    const afterDash = trimmed.substring(1);
   400→    // Should be followed by space or be end of line (for empty array items)
   401→    if (afterDash && !afterDash.startsWith(" ")) {
   402→      // Unless it's part of a negative number or date
   403→      if (!afterDash[0].match(/[0-9]/)) {
   404→        return {
   405→          valid: false,
   406→          error: {
   407→            line: lineNumber,
   408→            message: "Invalid array marker (dash must be followed by space)",
   409→          },
   410→        };
   411→      }
   412→    }
   413→  }
   414→
   415→  return null;
   416→}
   417→
   418→/**
   419→ * Update indentation stack based on line content.
   420→ */
   421→function updateIndentStack(
   422→  stack: number[],
   423→  indent: number,
   424→  line: string
   425→): void {
   426→  // Pop stack if indentation decreased
   427→  while (stack.length > 0 && indent < stack[stack.length - 1]) {
   428→    stack.pop();
   429→  }
   430→
   431→  // Add to stack if this line indicates a nested structure
   432→  if (
   433→    line.includes(":") &&
   434→    !line.trim().startsWith("-") &&
   435→    !line.endsWith(":")
   436→  ) {
   437→    // Key-value pair that might have nested content
   438→    if (stack.length === 0 || indent > stack[stack.length - 1]) {
   439→      stack.push(indent);
   440→    }
   441→  } else if (line.trim().startsWith("-")) {
   442→    // Array item
   443→    if (stack.length === 0 || indent > stack[stack.length - 1]) {
   444→      stack.push(indent);
   445→    }
   446→  }
   447→}
