     4→
     5→/**
     6→ * Integration tests for YAML validator.
     7→ *
     8→ * Tests the validateYamlFile() function through the CLI entry point
     9→ * using actual file I/O, exit codes, and stream output routing.
    10→ *
    11→ * Tests cover:
    12→ * - Valid YAML file validation (exit code 0, stdout success message)
    13→ * - Invalid YAML file validation (exit code 1, stderr error message)
    14→ * - File not found error handling (exit code 1, descriptive error)
    15→ * - Output stream routing (stdout vs stderr)
    16→ * - Error messages include line numbers
    17→ * - Backward compatibility with greet command
    18→ */
    19→
    20→describe("yaml validator - file I/O integration tests", () => {
    21→  const testDir = "./test_yaml_files_integration";
    22→
    23→  beforeAll(() => {
    24→    if (!existsSync(testDir)) {
    25→      mkdirSync(testDir, { recursive: true });
    26→    }
    27→  });
    28→
    29→  afterAll(() => {
    30→    try {
    31→      // Clean up all test files created in the directory
    32→      const files = [
    33→        `${testDir}/valid.yaml`,
    34→        `${testDir}/valid_stdout.yaml`,
    35→        `${testDir}/invalid.yaml`,
    36→        `${testDir}/invalid_stderr.yaml`,
    37→        `${testDir}/error_with_line.yaml`,
    38→        `${testDir}/empty.yaml`,
    39→        `${testDir}/unbalanced.yaml`,
    40→        `${testDir}/unclosed_bracket.yaml`,
    41→        `${testDir}/complex.yaml`,
    42→      ];
    43→
    44→      for (const file of files) {
    45→        if (existsSync(file)) {
    46→          unlinkSync(file);
    47→        }
    48→      }
    49→
    50→      if (existsSync(testDir)) {
    51→        Bun.spawnSync(["rmdir", testDir], { stdio: "ignore" });
    52→      }
    53→    } catch {
    54→      // Cleanup errors are acceptable in test teardown
    55→    }
    56→  });
    57→
    58→  test("valid YAML file returns exit code 0", async () => {
    59→    const testFile = `${testDir}/valid.yaml`;
    60→    const content = `name: test-app
    61→version: 1.0.0
    62→description: A test application`;
    63→    writeFileSync(testFile, content);
    64→
    65→    const proc = spawn(["bun", "run", "dev", "validate", testFile], {
    66→      stdout: "pipe",
