/**
 * YAML file validator with error handling.
 */

import { validateYamlSyntax } from "./utils";

/**
 * Validates a YAML file and outputs results to stdout/stderr.
 *
 * Reads the specified file, validates its YAML syntax, and outputs:
 * - Success message to stdout if YAML is valid (exit code 0)
 * - Error message to stderr if YAML is invalid (exit code 1)
 *
 * Handles file I/O errors gracefully:
 * - File not found: descriptive error message, exit code 1
 * - Permission denied: descriptive error message, exit code 1
 * - Read errors: descriptive error message, exit code 1
 *
 * @param filePath - Path to the YAML file to validate
 * @returns Promise that resolves when validation is complete (via process.exit)
 *
 * @example
 * // Validate a YAML file
 * await validateYamlFile("config.yaml");
 * // Outputs: "YAML is valid: config.yaml" and exits with code 0
 *
 * @example
 * // Handle invalid YAML
 * await validateYamlFile("bad.yaml");
 * // Outputs: "YAML error in bad.yaml at line 5: Unclosed quote" to stderr and exits with code 1
 */
export async function validateYamlFile(filePath: string): Promise<void> {
  try {
    const content = await Bun.file(filePath).text();
    const result = validateYamlSyntax(content);

    if (result.valid) {
      console.log(`YAML is valid: ${filePath}`);
      process.exit(0);
    } else {
      const errorMsg = `YAML error in ${filePath} at line ${result.error!.line}: ${result.error!.message}`;
      console.error(errorMsg);
      process.exit(1);
    }
  } catch (error) {
    const err = error as NodeJS.ErrnoException;

    if (err.code === "ENOENT") {
      console.error(`File not found: ${filePath}`);
    } else if (err.code === "EACCES") {
      console.error(`Permission denied: ${filePath}`);
    } else {
      console.error(`Error reading file: ${err.message}`);
    }
    process.exit(1);
  }
}

