     1→/**
     2→ * YAML file validator with error handling.
     3→ */
     4→
     5→import { validateYamlSyntax } from "./utils";
     6→
     7→/**
     8→ * Validates a YAML file and outputs results to stdout/stderr.
     9→ *
    10→ * Reads the specified file, validates its YAML syntax, and outputs:
    11→ * - Success message to stdout if YAML is valid (exit code 0)
    12→ * - Error message to stderr if YAML is invalid (exit code 1)
    13→ *
    14→ * Handles file I/O errors gracefully:
    15→ * - File not found: descriptive error message, exit code 1
    16→ * - Permission denied: descriptive error message, exit code 1
    17→ * - Read errors: descriptive error message, exit code 1
    18→ *
    19→ * @param filePath - Path to the YAML file to validate
    20→ * @returns Promise that resolves when validation is complete (via process.exit)
    21→ *
    22→ * @example
    23→ * // Validate a YAML file
    24→ * await validateYamlFile("config.yaml");
    25→ * // Outputs: "YAML is valid: config.yaml" and exits with code 0
    26→ *
    27→ * @example
    28→ * // Handle invalid YAML
    29→ * await validateYamlFile("bad.yaml");
    30→ * // Outputs: "YAML error in bad.yaml at line 5: Unclosed quote" to stderr and exits with code 1
    31→ */
    32→export async function validateYamlFile(filePath: string): Promise<void> {
    33→  try {
    34→    const content = await Bun.file(filePath).text();
    35→    const result = validateYamlSyntax(content);
    36→
    37→    if (result.valid) {
    38→      console.log(`YAML is valid: ${filePath}`);
    39→      process.exit(0);
    40→    } else {
    41→      const errorMsg = `YAML error in ${filePath} at line ${result.error!.line}: ${result.error!.message}`;
    42→      console.error(errorMsg);
    43→      process.exit(1);
    44→    }
    45→  } catch (error) {
    46→    const err = error as NodeJS.ErrnoException;
    47→
    48→    if (err.code === "ENOENT") {
    49→      console.error(`File not found: ${filePath}`);
    50→    } else if (err.code === "EACCES") {
    51→      console.error(`Permission denied: ${filePath}`);
    52→    } else {
    53→      console.error(`Error reading file: ${err.message}`);
    54→    }
    55→    process.exit(1);
    56→  }
    57→}
    58→

