import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { validateYamlSyntax } from "./utils";
import { writeFileSync, unlinkSync } from "fs";
import { existsSync } from "fs";

/**
 * Integration tests for YAML validator.
 *
 * Tests cover:
 * - Valid YAML syntax detection
 * - Invalid YAML syntax detection (unclosed quotes, bad indentation, unbalanced braces)
 * - File I/O error handling (file not found, permission denied)
 * - Output message formatting and exit codes
 * - Backward compatibility with existing commands
 */

describe("yaml validator - syntax validation", () => {
  test("valid YAML with simple key-value pairs", () => {
    const yaml = "name: my-app\nversion: 1.0.0";
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("valid YAML with nested structure", () => {
    const yaml = `app:
  name: my-app
  version: 1.0.0
  features:
    - logging
    - monitoring`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with array items", () => {
    const yaml = `items:
  - name: item1
    value: 100
  - name: item2
    value: 200`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with quoted strings", () => {
    const yaml = `name: "quoted value"
description: 'another quoted'`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with comments", () => {
    const yaml = `# This is a comment
name: my-app  # inline comment
version: 1.0.0`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with empty lines", () => {
    const yaml = `name: my-app

version: 1.0.0

description: A test app`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("invalid YAML - unclosed double quote", () => {
    const yaml = `name: "unclosed`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.line).toBe(1);
    expect(result.error?.message).toContain("Unclosed");
  });

  test("invalid YAML - unclosed single quote", () => {
    const yaml = `description: 'incomplete`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.line).toBe(1);
    expect(result.error?.message).toContain("Unclosed");
  });

  test("invalid YAML - unbalanced closing brace", () => {
    const yaml = `data: {key: value}
extra: }`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("Unbalanced");
  });

  test("invalid YAML - unbalanced closing bracket", () => {
    const yaml = `items: [1, 2, 3]
end: ]`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("Unbalanced");
  });

  test("invalid YAML - unclosed brace", () => {
    const yaml = `data: {key: value`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("Unclosed");
  });

  test("invalid YAML - unclosed bracket", () => {
    const yaml = `items: [1, 2, 3`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("Unclosed");
  });

  test("invalid YAML - tabs in indentation", () => {
    const yaml = `name: my-app\n\tversion: 1.0.0`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("Tabs");
  });

  test("invalid YAML - invalid colon placement", () => {
    const yaml = `name:value: 123`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("colon");
  });

  test("invalid YAML - invalid array marker", () => {
    const yaml = `items:
  -item1
  - item2`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.message).toContain("array marker");
  });

  test("valid YAML - URLs in quoted strings", () => {
    const yaml = `url: "https://example.com"
api: "http://api.example.com:8080"`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("empty YAML file", () => {
    const yaml = "";
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("YAML with only comments", () => {
    const yaml = `# Comment 1
# Comment 2
# Comment 3`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with escaped quotes in strings", () => {
    const yaml = `message: "He said \\"Hello\\""`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with multiline string marker", () => {
    const yaml = `description: |
  This is a multiline
  string that spans
  multiple lines
name: my-app`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("valid YAML with block quote", () => {
    const yaml = `description: >
  This is a long string
  that will be folded
  into a single line
name: my-app`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("error includes line number", () => {
    const yaml = `line1: valid
line2: valid
line3: "unclosed
line4: valid`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
    expect(result.error?.line).toBe(3);
  });
});

describe("yaml validator - file operations", () => {
  const testDir = "./test_yaml_files";
  const testFile = `${testDir}/test.yaml`;
  const invalidFile = `${testDir}/invalid.yaml`;

  beforeAll(() => {
    // Create test directory if it doesn't exist
    if (!existsSync(testDir)) {
      Bun.spawnSync(["mkdir", "-p", testDir]);
    }
  });

  afterAll(() => {
    // Clean up test files
    try {
      if (existsSync(testFile)) unlinkSync(testFile);
      if (existsSync(invalidFile)) unlinkSync(invalidFile);
      if (existsSync(testDir)) Bun.spawnSync(["rmdir", testDir]);
    } catch {
      // Ignore cleanup errors
    }
  });

  test("valid YAML file passes validation", () => {
    const content = `name: test-app
version: 1.0.0`;
    writeFileSync(testFile, content);

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("invalid YAML file fails validation", () => {
    const content = `name: "unclosed quote`;
    writeFileSync(invalidFile, content);

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(false);
    expect(result.error?.line).toBeGreaterThan(0);
  });

  test("complex valid YAML structure", () => {
    const content = `version: 1.0
metadata:
  name: complex-app
  version: 2.0
  tags:
    - production
    - critical
config:
  database:
    host: localhost
    port: 5432
    credentials:
      user: admin
      password: "secret123"
  cache:
    enabled: true
    ttl: 3600
features:
  - name: feature-1
    enabled: true
  - name: feature-2
    enabled: false
    config:
      timeout: 30`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with special characters in strings", () => {
    const content = `special: "value with @#$%^&*() chars"
path: /home/user/docs/file.txt
math: 2+2=4`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with numeric values", () => {
    const content = `integer: 42
float: 3.14
negative: -100
scientific: 1.2e-3
hex: 0x1a`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with boolean values", () => {
    const content = `enabled: true
disabled: false
yes_val: yes
no_val: no`;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });

  test("YAML with null values", () => {
    const content = `null_value: null
tilde_value: ~
empty: `;

    const result = validateYamlSyntax(content);
    expect(result.valid).toBe(true);
  });
});

describe("yaml validator - edge cases", () => {
  test("single character key", () => {
    const yaml = `a: 1`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("key with dash characters", () => {
    const yaml = `my-app-name: value
another-key: another-value`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("key with underscores", () => {
    const yaml = `my_key: value
another_key: another_value`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("nested arrays", () => {
    const yaml = `matrix:
  - [1, 2, 3]
  - [4, 5, 6]`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("mixed inline and block styles", () => {
    const yaml = `inline: {key1: value1, key2: value2}
block:
  key1: value1
  key2: value2`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("comment with hash inside quoted string", () => {
    const yaml = `message: "This has a # hash mark"
description: 'Another # hash'`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("value that looks like YAML but is quoted", () => {
    const yaml = `key: "- item"`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("whitespace-only line between content", () => {
    const yaml = `key1: value1

key2: value2`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("large indentation levels", () => {
    const yaml = `level1:
  level2:
    level3:
      level4:
        level5: value`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("line with only indentation and dash", () => {
    const yaml = `items:
  -`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("multiple colons in quoted value", () => {
    const yaml = `url: "http://example.com:8080:9090"`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("parenthesis in unquoted value", () => {
    const yaml = `command: "echo (hello world)"`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("balanced parenthesis in quoted string", () => {
    const yaml = `formula: "x = (a + b) * (c - d)"`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(true);
  });

  test("unbalanced parenthesis error", () => {
    const yaml = `data: (incomplete`;
    const result = validateYamlSyntax(yaml);
    expect(result.valid).toBe(false);
