import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { writeFileSync, unlinkSync, existsSync, mkdirSync } from "fs";
import { spawn } from "bun";

/**
 * Integration tests for YAML validator.
 *
 * Tests the validateYamlFile() function through the CLI entry point
 * using actual file I/O, exit codes, and stream output routing.
 *
 * Tests cover:
 * - Valid YAML file validation (exit code 0, stdout success message)
 * - Invalid YAML file validation (exit code 1, stderr error message)
 * - File not found error handling (exit code 1, descriptive error)
 * - Output stream routing (stdout vs stderr)
 * - Error messages include line numbers
 * - Backward compatibility with greet command
 */

describe("yaml validator - file I/O integration tests", () => {
  const testDir = "./test_yaml_files_integration";

  beforeAll(() => {
    if (!existsSync(testDir)) {
      mkdirSync(testDir, { recursive: true });
    }
  });

  afterAll(() => {
    try {
      const files = Bun.file(testDir);
      const fileList = await files.arrayBuffer();
      // Simple cleanup: remove test files if they exist
      const validFile = `${testDir}/valid.yaml`;
      const invalidFile = `${testDir}/invalid.yaml`;
      const emptyFile = `${testDir}/empty.yaml`;

      if (existsSync(validFile)) unlinkSync(validFile);
      if (existsSync(invalidFile)) unlinkSync(invalidFile);
      if (existsSync(emptyFile)) unlinkSync(emptyFile);

      if (existsSync(testDir)) {
        Bun.spawnSync(["rmdir", testDir], { stdio: "ignore" });
      }
    } catch {
      // Cleanup errors are acceptable in test teardown
    }
  });

  test("valid YAML file returns exit code 0", async () => {
    const testFile = `${testDir}/valid.yaml`;
    const content = `name: test-app
version: 1.0.0
description: A test application`;
    writeFileSync(testFile, content);

    const proc = spawn(["bun", "run", "dev", "validate", testFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    expect(exitCode).toBe(0);
  });

  test("valid YAML file outputs success message to stdout", async () => {
    const testFile = `${testDir}/valid_stdout.yaml`;
    const content = `name: my-app
version: 2.0.0`;
    writeFileSync(testFile, content);

    const proc = spawn(["bun", "run", "dev", "validate", testFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const stdout = await new Response(proc.stdout).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(0);
    expect(stdout).toContain("YAML is valid");
    expect(stdout).toContain(testFile);
  });

  test("invalid YAML file returns exit code 1", async () => {
    const testFile = `${testDir}/invalid.yaml`;
    const content = `name: "unclosed quote`;
    writeFileSync(testFile, content);

    const proc = spawn(["bun", "run", "dev", "validate", testFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    expect(exitCode).toBe(1);
  });

  test("invalid YAML outputs error message to stderr", async () => {
    const testFile = `${testDir}/invalid_stderr.yaml`;
    const content = `name: "unclosed quote
version: 1.0.0`;
    writeFileSync(testFile, content);

    const proc = spawn(["bun", "run", "dev", "validate", testFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stderr).toContain("YAML error");
  });

  test("error message includes line number", async () => {
    const testFile = `${testDir}/error_with_line.yaml`;
    const content = `line1: valid
line2: valid
line3: "unclosed
line4: valid`;
    writeFileSync(testFile, content);

    const proc = spawn(["bun", "run", "dev", "validate", testFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stderr).toContain("line 3");
  });

  test("file not found returns exit code 1", async () => {
    const nonexistentFile = `${testDir}/does_not_exist.yaml`;

    const proc = spawn(["bun", "run", "dev", "validate", nonexistentFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    expect(exitCode).toBe(1);
  });

  test("file not found outputs error to stderr", async () => {
    const nonexistentFile = `${testDir}/missing_file.yaml`;

    const proc = spawn(["bun", "run", "dev", "validate", nonexistentFile], {
      stdout: "pipe",
      stderr: "pipe",
    });

    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    expect(exitCode).toBe(1);
    expect(stderr).toContain("File not found");
  });

  test("empty valid YAML file returns exit code 0", async () => {
